using Microsoft.Extensions.AI;
using OpenAI;
using System.ComponentModel;
using System.Text.Json;

Console.WriteLine("Research Agent Starting...");

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY") ?? "sk-placeholder";
var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

var openAiClient = new OpenAIClient(apiKey);
IChatClient chatClient = openAiClient.GetChatClient(modelId).AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

var notes = new NoteTaker();

var chatOptions = new ChatOptions
{
    Tools =
    [
        AIFunctionFactory.Create(SearchWeb),
        AIFunctionFactory.Create(notes.AddNote),
        AIFunctionFactory.Create(notes.GetNotes),
    ]
};

var topic = args.Length > 0 ? string.Join(' ', args) : "recent advances in quantum computing";

Console.WriteLine($"\nResearching topic: {topic}\n");

var messages = new List<ChatMessage>
{
    new(ChatRole.System, """
        You are a research agent. Your job is to research a given topic thoroughly.

        Follow these steps:
        1. Search the web for information on the topic (make 2-3 searches with different queries)
        2. Take notes on the key findings from each search
        3. After gathering enough information, review your notes and provide a comprehensive summary

        Always use the tools available to you. Take detailed notes as you go.
        """),
    new(ChatRole.User, $"Please research the following topic and provide a summary: {topic}")
};

var response = await chatClient.GetResponseAsync(messages, chatOptions);

Console.WriteLine("\n=== Research Summary ===\n");
Console.WriteLine(response.Text);

Console.WriteLine("\n=== Collected Notes ===\n");
foreach (var note in notes.AllNotes)
{
    Console.WriteLine($"• {note}");
}

// --- Tool Definitions ---

[Description("Searches the web for information on a query and returns relevant results.")]
static string SearchWeb([Description("The search query")] string query)
{
    Console.WriteLine($"  [Tool] Searching web for: \"{query}\"");

    // Simulated search results for demonstration purposes
    var results = new[]
    {
        new { Title = $"Latest findings on: {query}", Snippet = $"Research shows significant progress in {query}. Multiple studies published in 2025-2026 highlight breakthroughs in this area." },
        new { Title = $"{query} - Overview and Recent Developments", Snippet = $"Experts note that {query} has seen rapid advancement. Key developments include improved methodologies and broader applications." },
        new { Title = $"Future of {query}", Snippet = $"Analysts predict continued growth in {query}. Industry leaders are investing heavily in related technologies and research." }
    };

    return JsonSerializer.Serialize(results, new JsonSerializerOptions { WriteIndented = true });
}

// --- Note-Taking Tool ---

class NoteTaker
{
    private readonly List<string> _notes = [];

    public IReadOnlyList<string> AllNotes => _notes;

    [Description("Adds a note to the research notebook for later reference.")]
    public string AddNote([Description("The note content to save")] string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  [Tool] Note added ({_notes.Count} total)");
        return $"Note saved. You now have {_notes.Count} note(s).";
    }

    [Description("Retrieves all notes taken so far.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes taken yet.";

        return string.Join("\n", _notes.Select((n, i) => $"{i + 1}. {n}"));
    }
}

